INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("メルクリウス財団", 12, 20, "傭兵などのアルバイト", "O", "ヒューマン", 163, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "仕事も私事も効率優先な傭兵少女", 108001, "田所あずさ", 0, "ミフユ（サマー）", 49, 11, 11);
