INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("悪魔偽王国軍（ディアボロス）", 7, 14, "プリンを食べること", "B", "魔族", 130, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリン大好きゴースト娘", 108201, "雨宮天", 0, "ミヤコ（ハロウィン）", 32, 23, 1);
