INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("カルミナ", 4, 17, "各種楽器", "O", "ヒューマン", 163, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "人々を守るために歌う、唱喚士の少女", 108401, "福原綾香", 0, "チカ（クリスマス）", 46, 3, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("サレンディア救護院", 9, 12, "観劇、おままごと", "B", "ヒューマン", 150, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "泣き虫で臆病な守ってあげたい女の子", 108501, "植田佳奈", 0, "クルミ（クリスマス）", 40, 9, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("サレンディア救護院", 9, 14, "屋内でできる遊び", "B", "ヒューマン", 148, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "ぷうきちといつも一緒！", 108601, "芹澤優", 0, "アヤネ（クリスマス）", 38, 10, 5);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("トゥインクルウィッシュ", 2, 16, "人助け、応援", "A", "獣人族", 155, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", 108701, "東山奈央", 0, "ヒヨリ（ニューイヤー）", 44, 27, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("トゥインクルウィッシュ", 2, 17, "料理、人間観察", "O", "ヒューマン", 158, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", 108801, "種田梨沙", 0, "ユイ（ニューイヤー）", 47, 5, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("トゥインクルウィッシュ", 2, 18, "読書、乗馬、お茶", "B", "魔族", 163, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", 108901, "早見沙織", 0, "レイ（ニューイヤー）", 46, 12, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("トワイライトキャラバン", 13, 16, "実験、裁縫、料理", "B", "魔族", 154, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "運命の相手に一途すぎる乙女", 109001, "橋本ちなみ", 0, "エリコ（バレンタイン）", 43, 30, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("ラビリンス", 3, 18, "家事全般", "O", "ヒューマン", 168, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "お姉ちゃんがお世話してあげるからねっ！", 109101, "生天目仁美", 0, "シズル（バレンタイン）", 54, 24, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("？？？", "", 17, "読書", "AB", "ヒューマン", 156, "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", "英霊と契約を結んだマナリアの天才王女", 109201, "日笠陽子", 0, "アン", 55, 1, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("？？？", "", 16, "食べること、眠ること", "O", "ヒューマン", 144, "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", "マナリア魔法学院の新入生", 109301, "こやまきみこ", 0, "ルゥ", 45, 4, 2);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("？？？", "", 17, "ピアノ", "B", "半人半竜", 167, "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", "人を超越した力を有す心優しい竜姫", 109401, "福原綾香", 0, "グレア", 67, 3, 11);
